#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=4
PROJECT_SETUP_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$PROJECT_SETUP_DIR"
ENV_FILE="$PROJECT_SETUP_DIR/.env"
PYTHON_SETUP_BIN="$PROJECT_SETUP_DIR/.venv/bin/python"
if [[ ! -x "$PYTHON_SETUP_BIN" ]]; then PYTHON_SETUP_BIN="$(command -v python3)"; fi
BOOTSTRAP_HELPER="$PROJECT_SETUP_DIR/scripts/setup-telegram-thunderbird/telegram_bootstrap.py"
PACKAGE_XPI="/home/naoufel/Downloads/Enrich-setup/thunderbird-mcp-enrich-exact-reply.xpi"

banner "Enrich : Telegram et Thunderbird"

stage "Telegram : créer le bot et enregistrer son token"
open_url "https://t.me/BotFather"
step "Dans Telegram, ouvre le compte officiel @BotFather et envoie /newbot."
step "Nom proposé : Contexte Lab Enrich. Choisis un username disponible terminé par bot."
step "Copie le token fourni. Si tu as déjà un bot dédié à Enrich, utilise son token."
note "Le token est saisi ici de manière masquée ; ne le colle pas dans la conversation Codex."
while true; do
  ask_secret TELEGRAM_BOT_TOKEN "Colle le token BotFather puis Entrée :"
  if [[ "$TELEGRAM_BOT_TOKEN" =~ ^[0-9]+:[A-Za-z0-9_-]+$ ]]; then break; fi
  warn "Format inattendu. Colle uniquement le token, sans guillemets ni espaces."
done
BOT_SETUP_USERNAME="$(printf '%s\n' "$TELEGRAM_BOT_TOKEN" | "$PYTHON_SETUP_BIN" "$BOOTSTRAP_HELPER" username)"
write_env TELEGRAM_BOT_TOKEN "$TELEGRAM_BOT_TOKEN"
chmod 600 "$ENV_FILE"
note "Token vérifié et enregistré. Bot : @$BOT_SETUP_USERNAME."

stage "Telegram : associer ton compte et ton chat privés"
open_url "https://t.me/$BOT_SETUP_USERNAME"
step "Depuis le compte Telegram qui approuvera les emails, clique Démarrer dans ce chat privé."
SETUP_NONCE="$("$PYTHON_SETUP_BIN" -c 'import secrets; print("ENRICH_SETUP_" + secrets.token_hex(16))')"
step "Envoie exactement ce message au bot :"
say "$SETUP_NONCE"
pause "Quand le message est envoyé, appuie sur Entrée."
while true; do
  if SETUP_IDS="$(printf '%s\n%s\n' "$TELEGRAM_BOT_TOKEN" "$SETUP_NONCE" | "$PYTHON_SETUP_BIN" "$BOOTSTRAP_HELPER" operator)"; then break; fi
  pause "Vérifie le compte/chat et envoie le code ci-dessus, puis Entrée pour réessayer."
done
read -r TELEGRAM_OPERATOR_ID TELEGRAM_CHAT_ID <<< "$SETUP_IDS"
say "Compte opérateur : $TELEGRAM_OPERATOR_ID ; chat privé : $TELEGRAM_CHAT_ID."
if ! confirm "Enregistrer ce compte comme seul opérateur autorisé ?"; then exit 0; fi
write_env TELEGRAM_OPERATOR_ID "$TELEGRAM_OPERATOR_ID"
write_env TELEGRAM_CHAT_ID "$TELEGRAM_CHAT_ID"
chmod 600 "$ENV_FILE"

stage "Thunderbird : installer l’adaptation de réponse exacte"
open_url "https://support.mozilla.org/en-US/kb/installing-addon-thunderbird"
step "Dans Thunderbird : menu ≡ → Modules complémentaires et thèmes → Extensions."
step "Menu engrenage → Installer un module depuis un fichier…"
step "Sélectionne ce paquet local :"
say "$PACKAGE_XPI"
step "Vérifie le nom Thunderbird MCP — Enrich et la version 0.9.2.1 ; accepte la mise à jour."
note "Cette version conserve les préférences. Ses mises à jour automatiques sont désactivées pour préserver le correctif local."
step "Redémarre Thunderbird si demandé ; laisse-le ouvert pour les sondes."
pause "Quand l’extension adaptée est active, appuie sur Entrée."

stage "Thunderbird : autoriser l’envoi approuvé et vérifier"
step "Ouvre les options de l’extension Thunderbird MCP — Enrich."
say "La case Block skipReview (default) impose une seconde revue dans Thunderbird."
say "La décocher autorise l’envoi direct pour les clients MCP ; Enrich exige toujours l’approbation Telegram de la version exacte."
if confirm "Configurer ce mode d’envoi direct dans les options de l’extension ?"; then
  step "Décoche Block skipReview (default) -- require review for mail, events, and tasks."
  step "Ne modifie aucune autre option."
  pause "Après modification, appuie sur Entrée."
else
  note "Revue Thunderbird conservée : l’envoi autonome restera bloqué."
  SKIPPED+=("Mode d’envoi autonome : revue Thunderbird conservée par ton choix")
fi
bash scripts/cron_agent_dispatcher.sh --task readiness --probe
note "Résultat de la sonde (aucun email envoyé) :"
tail -n 30 "logs/outreach_cron_$(date +%Y-%m-%d).log"
note "telegram et thunderbird_exact_reply doivent être true. Le token Twenty reste une configuration distincte."
note "L’assistant n’installe aucun cron et n’envoie aucun email."
finish
